node --input-type=module -e "
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';

const THREAD = '1533603278816936168';
const MSG = '1533618747468681339';
const env = await loadEnv();
const token = botToken(env);
if (!token) { console.error('no AVA_DISCORD_BOT_TOKEN'); process.exit(1); }
const fetchJson = makeFetchJson(token);

async function tryGet(channelId, messageId) {
  try {
    return await fetchJson('/channels/' + channelId + '/messages/' + messageId);
  } catch (e) {
    return { error: e.message };
  }
}

const direct = await tryGet(THREAD, MSG);
console.log('=== DIRECT FROM BOATS THREAD ===');
console.log(JSON.stringify(direct, null, 2));

if (direct && !direct.error) {
  const around = await fetchJson('/channels/' + THREAD + '/messages?around=' + MSG + '&limit=15');
  console.log('=== AROUND ===');
  for (const m of around) {
    const author = m.author?.global_name || m.author?.username || '?';
    const aid = m.author?.id;
    console.log('---');
    console.log(m.id, author, aid, new Date(m.timestamp).toISOString());
    console.log(m.content);
    if (m.referenced_message) {
      console.log('  ref:', m.referenced_message.id, (m.referenced_message.author?.username||''), String(m.referenced_message.content||'').slice(0,120));
    }
    if (m.reactions?.length) console.log('  reactions:', m.reactions.map(r => r.emoji?.name + ':' + r.count).join(', '));
  }
  // parent channel starter
  try {
    const starter = await fetchJson('/channels/' + THREAD + '/messages/' + THREAD);
    console.log('=== THREAD STARTER ===');
    console.log(JSON.stringify({ id: starter.id, author: starter.author?.username, content: starter.content?.slice(0,800) }, null, 2));
  } catch (e) {
    console.log('starter err', e.message);
  }
}
"

