node --input-type=module -e "
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const THREAD = '1533603278816936168';
const MSG = '1533618747468681339';
const env = await loadEnv();
const token = botToken(env);
const fetchJson = makeFetchJson(token);
const m = await fetchJson('/channels/' + THREAD + '/messages/' + MSG);
const att = m.attachments?.[0];
console.log('url', att?.url);
console.log('proxy', att?.proxy_url);
const out = path.join(os.tmpdir(), 'ava-msg-nothin.png');
for (const u of [att.url, att.proxy_url]) {
  try {
    const res = await fetch(u, { headers: { Authorization: 'Bot ' + token } });
    console.log('try', u.slice(0,80), res.status, res.headers.get('content-type'));
    if (res.ok) {
      fs.writeFileSync(out, Buffer.from(await res.arrayBuffer()));
      console.log('saved', out, fs.statSync(out).size);
      break;
    }
    // without auth
    const res2 = await fetch(u);
    console.log('noauth', res2.status);
    if (res2.ok) {
      fs.writeFileSync(out, Buffer.from(await res2.arrayBuffer()));
      console.log('saved', out, fs.statSync(out).size);
      break;
    }
  } catch (e) { console.log('err', e.message); }
}
"

